1	package edgefleet
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"time"
8		"unicode/utf8"
9	)
10	
11	// Heartbeat is one telemetry record reported by a node.
12	//
13	// JSON input uses snake_case field names:
14	//
15	//	node          string   node id (required, non-empty)
16	//	seq           integer  sequence number (required, > 0)
17	//	collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00 (required)
18	//	version       string   version (required, non-empty)
19	//	height        integer  block height (required, >= 0)
20	//	missed        integer  cumulative missed duties (required, >= 0)
21	type Heartbeat struct {
22		NodeID      string    `json:"node"`
23		Seq         int64     `json:"seq"`
24		CollectedAt time.Time `json:"collected_at"`
25		Version     string    `json:"version"`
26		Height      int64     `json:"height"`
27		Missed      int64     `json:"missed"`
28	}
29	
30	// heartbeatFields enumerates every field that must be explicitly provided.
31	var heartbeatFields = []string{"node", "seq", "collected_at", "version", "height", "missed"}
32	
33	// fieldIssue classifies the way a field value violates a rule. Together with
34	// the field name and the offending numeric value it identifies the rule that
35	// failed, without carrying any wording. Each trust boundary renders the
36	// failure in its own message style and locates it in its own context, but the
37	// rules themselves — which values are legal — live in the check* functions
38	// below exactly once.
39	type fieldIssue int
40	
41	const (
42		issueEmpty          fieldIssue = iota // a required string is ""
43		issueInvalidUnicode                   // node id is not lossless text
44		issueNotPositive                      // integer must be > 0
45		issueNegative                         // integer must be >= 0
46		issueMissingInstant                   // collected_at is the zero instant
47	)
48	
49	// fieldValueError names the field whose value rule was violated.
50	type fieldValueError struct {
51		field string
52		issue fieldIssue
53		value int64
54	}
55	
56	// checkNodeIDValue holds the single node-id value rule: non-empty, valid
57	// Unicode text. The raw-JSON boundary additionally checks the un-decoded
58	// token (see validateRawNodeText); for a value already decoded from such a
59	// token the Unicode branch can never fire, but both submit entries and the
60	// stored-data read enforce the same rule through this one function.
61	func checkNodeIDValue(node string) *fieldValueError {
62		if node == "" {
63			return &fieldValueError{field: "node", issue: issueEmpty}
64		}
65		if !utf8.ValidString(node) {
66			return &fieldValueError{field: "node", issue: issueInvalidUnicode}
67		}
68		return nil
69	}
70	
71	// checkNonEmptyString holds the single non-empty-string value rule, shared by
72	// every field that uses it (currently version).
73	func checkNonEmptyString(field, value string) *fieldValueError {
74		if value == "" {
75			return &fieldValueError{field: field, issue: issueEmpty}
76		}
77		return nil
78	}
79	
80	// checkPositiveInt holds the single positive-integer rule (seq).
81	func checkPositiveInt(field string, value int64) *fieldValueError {
82		if value <= 0 {
83			return &fieldValueError{field: field, issue: issueNotPositive, value: value}
84		}
85		return nil
86	}
87	
88	// checkNonNegativeInt holds the single non-negative-integer rule (height,
89	// missed). An explicit zero is genuine telemetry and passes.
90	func checkNonNegativeInt(field string, value int64) *fieldValueError {
91		if value < 0 {
92			return &fieldValueError{field: field, issue: issueNegative, value: value}
93		}
94		return nil
95	}
96	
97	// checkCollectedAtValue holds the single rule that a collection instant must
98	// actually be present (not the zero time).
99	func checkCollectedAtValue(collected time.Time) *fieldValueError {
100		if collected.IsZero() {
101			return &fieldValueError{field: "collected_at", issue: issueMissingInstant}
102		}
103		return nil
104	}
105	
106	// checkHeartbeatValues runs every context-free field-value rule in the single
107	// rejection order shared by the direct-submit and stored-data boundaries:
108	// node, seq, version, height, missed, then collected_at. It deliberately does
109	// NOT compare against a receive time: reading saved history has no receive
110	// time, and that submit-only rule lives in checkCollectedAtTiming.
111	func checkHeartbeatValues(h Heartbeat) *fieldValueError {
112		if e := checkNodeIDValue(h.NodeID); e != nil {
113			return e
114		}
115		if e := checkPositiveInt("seq", h.Seq); e != nil {
116			return e
117		}
118		if e := checkNonEmptyString("version", h.Version); e != nil {
119			return e
120		}
121		if e := checkNonNegativeInt("height", h.Height); e != nil {
122			return e
123		}
124		if e := checkNonNegativeInt("missed", h.Missed); e != nil {
125			return e
126		}
127		return checkCollectedAtValue(h.CollectedAt)
128	}
129	
130	// checkCollectedAtTiming holds the single receive-time rule, which belongs to
131	// submission only: a collection time later than the receive time is refused;
132	// the same instant expressed in another timezone is equal and allowed. The
133	// stored-data read path never calls this, so reading history introduces no
134	// current time and no extra time limit.
135	func checkCollectedAtTiming(collected, receiveTime time.Time) error {
136		if collected.After(receiveTime) {
137			return fmt.Errorf("collected_at %s is later than receive time %s",
138				collected.Format(time.RFC3339), receiveTime.Format(time.RFC3339))
139		}
140		return nil
141	}
142	
143	// directError renders a field rule failure in ValidateHeartbeat's wording,
144	// used when a caller submits an already constructed Heartbeat.
145	func (e *fieldValueError) directError() error {
146		switch {
147		case e.field == "node" && e.issue == issueEmpty:
148			return fmt.Errorf("node id is empty")
149		case e.field == "node" && e.issue == issueInvalidUnicode:
150			return fmt.Errorf("node id is not valid Unicode text: contains invalid UTF-8")
151		case e.field == "seq":
152			return fmt.Errorf("seq must be a positive integer, got %d", e.value)
153		case e.field == "version":
154			return fmt.Errorf("version is empty")
155		case e.field == "height":
156			return fmt.Errorf("height must be >= 0, got %d", e.value)
157		case e.field == "missed":
158			return fmt.Errorf("missed must be >= 0, got %d", e.value)
159		case e.field == "collected_at":
160			return fmt.Errorf("collected_at is missing or invalid")
161		default:
162			return fmt.Errorf("field %q has an invalid value", e.field)
163		}
164	}
165	
166	// decodeError renders a field rule failure in the wording used while decoding
167	// a strict JSON object (submit input and stored records alike).
168	func (e *fieldValueError) decodeError() error {
169		switch {
170		case e.field == "node" && e.issue == issueInvalidUnicode:
171			return fmt.Errorf("node id is not valid Unicode text: contains invalid UTF-8")
172		case e.field == "node":
173			return fmt.Errorf("node must not be empty")
174		case e.field == "seq":
175			return fmt.Errorf("seq must be a positive integer, got %d", e.value)
176		case e.field == "version":
177			return fmt.Errorf("version must not be empty")
178		case e.field == "height":
179			return fmt.Errorf("height must be >= 0, got %d", e.value)
180		case e.field == "missed":
181			return fmt.Errorf("missed must be >= 0, got %d", e.value)
182		default:
183			return fmt.Errorf("invalid value for field %q", e.field)
184		}
185	}
186	
187	// storedError renders a field rule failure for a record read from a saved
188	// file, prefixing the 1-based record position as stored-data errors do.
189	func (e *fieldValueError) storedError(position int) error {
190		switch {
191		case e.field == "node" && e.issue == issueInvalidUnicode:
192			return fmt.Errorf("record %d: field %q is not valid Unicode text", position, e.field)
193		case e.field == "node" || e.field == "version":
194			return fmt.Errorf("record %d: field %q must not be empty", position, e.field)
195		case e.field == "seq":
196			return fmt.Errorf("record %d: field %q must be a positive integer, got %d", position, e.field, e.value)
197		case e.field == "height" || e.field == "missed":
198			return fmt.Errorf("record %d: field %q must be >= 0, got %d", position, e.field, e.value)
199		case e.field == "collected_at":
200			return fmt.Errorf("record %d: field %q is missing or invalid", position, e.field)
201		default:
202			return fmt.Errorf("record %d: field %q has an invalid value", position, e.field)
203		}
204	}
205	
206	// ValidateHeartbeat checks the semantic rules for one record. receiveTime is
207	// the moment the platform received the batch; a collection time later than
208	// receive time is rejected. The field-value rules are shared with JSON
209	// parsing and the stored-file read path via checkHeartbeatValues; only the
210	// receive-time comparison is submit-specific.
211	func ValidateHeartbeat(h Heartbeat, receiveTime time.Time) error {
212		if e := checkHeartbeatValues(h); e != nil {
213			return e.directError()
214		}
215		return checkCollectedAtTiming(h.CollectedAt, receiveTime)
216	}
217	
218	// Equal reports whether two records are the same telemetry. Collection times
219	// are compared as instants, so the same moment expressed in different
220	// timezones compares equal.
221	func (h Heartbeat) Equal(o Heartbeat) bool {
222		return h.NodeID == o.NodeID &&
223			h.Seq == o.Seq &&
224			h.Version == o.Version &&
225			h.Height == o.Height &&
226			h.Missed == o.Missed &&
227			h.CollectedAt.Equal(o.CollectedAt)
228	}
229	
230	// ParseHeartbeats parses a JSON array of heartbeat objects. Every field must
231	// be explicitly provided; missing or unknown fields are rejected with a
232	// specific reason.
233	func ParseHeartbeats(data []byte, receiveTime time.Time) ([]Heartbeat, error) {
234		var raw []json.RawMessage
235		if err := json.Unmarshal(data, &raw); err != nil {
236			return nil, fmt.Errorf("input must be a JSON array of heartbeat objects: %w", err)
237		}
238		if len(raw) == 0 {
239			return nil, fmt.Errorf("no heartbeat records provided")
240		}
241		records := make([]Heartbeat, 0, len(raw))
242		for i, r := range raw {
243			h, err := parseOneHeartbeat(r, receiveTime)
244			if err != nil {
245				return nil, fmt.Errorf("record %d: %w", i+1, err)
246			}
247			records = append(records, h)
248		}
249		return records, nil
250	}
251	
252	// rejectNull reports an error when a required field's JSON value is null.
253	// A null value means the node did not report the field, which must not be
254	// silently saved as the zero value.
255	func rejectNull(raw json.RawMessage, field string) error {
256		if bytes.Equal(raw, []byte("null")) {
257			return fmt.Errorf("%s must not be null", field)
258		}
259		return nil
260	}
261	
262	// decodeStrictHeartbeatObject converts one JSON object's raw bytes into a
263	// Heartbeat while enforcing the field rules at every trust boundary: all
264	// fields must be present and non-null, unknown fields are rejected, and a
265	// field may never appear twice in the same object — even with the same
266	// value, and even when one spelling uses a JSON Unicode escape denoting the
267	// same key. A plain struct/map unmarshal would instead keep the last
268	// occurrence and let an absent field masquerade as the zero value. Both the
269	// submit input path and the stored-file read path must use it.
270	func decodeStrictHeartbeatObject(raw json.RawMessage) (Heartbeat, error) {
271		// Walk the object with a streaming decoder so duplicate field names are
272		// detected. Field names are compared as the JSON string they represent:
273		// "missed" and "m\u0069ssed" are the same field. A map-based unmarshal
274		// would silently keep only the last occurrence.
275		dec := json.NewDecoder(bytes.NewReader(raw))
276		tok, err := dec.Token()
277		if err != nil {
278			return Heartbeat{}, fmt.Errorf("record must be a JSON object: %w", err)
279		}
280		if d, ok := tok.(json.Delim); !ok || d != '{' {
281			return Heartbeat{}, fmt.Errorf("record must be a JSON object")
282		}
283	
284		fields := make(map[string]json.RawMessage)
285		for dec.More() {
286			keyTok, err := dec.Token()
287			if err != nil {
288				return Heartbeat{}, fmt.Errorf("invalid field: %w", err)
289			}
290			key, ok := keyTok.(string)
291			if !ok {
292				return Heartbeat{}, fmt.Errorf("field name must be a string")
293			}
294			if _, exists := fields[key]; exists {
295				return Heartbeat{}, fmt.Errorf("duplicate field %q", key)
296			}
297			var val json.RawMessage
298			if err := dec.Decode(&val); err != nil {
299				return Heartbeat{}, fmt.Errorf("invalid value for field %q: %w", key, err)
300			}
301			fields[key] = val
302		}
303		// Consume the closing brace.
304		if _, err := dec.Token(); err != nil {
305			return Heartbeat{}, fmt.Errorf("invalid record: %w", err)
306		}
307	
308		for _, f := range heartbeatFields {
309			if _, ok := fields[f]; !ok {
310				return Heartbeat{}, fmt.Errorf("missing required field %q", f)
311			}
312		}
313		for k := range fields {
314			if !containsString(heartbeatFields, k) {
315				return Heartbeat{}, fmt.Errorf("unknown field %q", k)
316			}
317		}
318	
319		var h Heartbeat
320	
321		if err := rejectNull(fields["node"], "node"); err != nil {
322			return Heartbeat{}, err
323		}
324		if err := json.Unmarshal(fields["node"], &h.NodeID); err != nil {
325			return Heartbeat{}, fmt.Errorf("node must be a string: %w", err)
326		}
327		if err := validateRawNodeText(fields["node"]); err != nil {
328			return Heartbeat{}, err
329		}
330		if e := checkNodeIDValue(h.NodeID); e != nil {
331			return Heartbeat{}, e.decodeError()
332		}
333	
334		if err := rejectNull(fields["seq"], "seq"); err != nil {
335			return Heartbeat{}, err
336		}
337		if err := json.Unmarshal(fields["seq"], &h.Seq); err != nil {
338			return Heartbeat{}, fmt.Errorf("seq must be an integer: %w", err)
339		}
340		if e := checkPositiveInt("seq", h.Seq); e != nil {
341			return Heartbeat{}, e.decodeError()
342		}
343	
344		if err := rejectNull(fields["collected_at"], "collected_at"); err != nil {
345			return Heartbeat{}, err
346		}
347		var collectedStr string
348		if err := json.Unmarshal(fields["collected_at"], &collectedStr); err != nil {
349			return Heartbeat{}, fmt.Errorf("collected_at must be a string: %w", err)
350		}
351		t, err := time.Parse(time.RFC3339, collectedStr)
352		if err != nil {
353			return Heartbeat{}, fmt.Errorf("collected_at must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00): %w", err)
354		}
355		h.CollectedAt = t
356	
357		if err := rejectNull(fields["version"], "version"); err != nil {
358			return Heartbeat{}, err
359		}
360		if err := json.Unmarshal(fields["version"], &h.Version); err != nil {
361			return Heartbeat{}, fmt.Errorf("version must be a string: %w", err)
362		}
363		if e := checkNonEmptyString("version", h.Version); e != nil {
364			return Heartbeat{}, e.decodeError()
365		}
366	
367		if err := rejectNull(fields["height"], "height"); err != nil {
368			return Heartbeat{}, err
369		}
370		if err := json.Unmarshal(fields["height"], &h.Height); err != nil {
371			return Heartbeat{}, fmt.Errorf("height must be an integer: %w", err)
372		}
373		if e := checkNonNegativeInt("height", h.Height); e != nil {
374			return Heartbeat{}, e.decodeError()
375		}
376	
377		if err := rejectNull(fields["missed"], "missed"); err != nil {
378			return Heartbeat{}, err
379		}
380		if err := json.Unmarshal(fields["missed"], &h.Missed); err != nil {
381			return Heartbeat{}, fmt.Errorf("missed must be an integer: %w", err)
382		}
383		if e := checkNonNegativeInt("missed", h.Missed); e != nil {
384			return Heartbeat{}, e.decodeError()
385		}
386	
387		return h, nil
388	}
389	
390	// validateRawNodeText checks the raw JSON string token of the node field
391	// before its decoded value is trusted. encoding/json silently rewrites
392	// invalid UTF-8 bytes and unpaired \u surrogate escapes to U+FFFD, which
393	// would merge distinct node ids into one replacement-char id and break the
394	// ownership check against stored files. The raw token must decode
395	// losslessly: every literal byte sequence must be valid UTF-8, and every \u
396	// escape must be a valid scalar value or a properly paired high/low
397	// surrogate pair. A literal "�" (or its \uFFFD escape) is valid text the
398	// user typed and is accepted; only undecodable input is rejected.
399	func validateRawNodeText(raw json.RawMessage) error {
400		raw = bytes.TrimSpace(raw)
401		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
402			return fmt.Errorf("node must be a string")
403		}
404		s := raw[1 : len(raw)-1]
405		for i := 0; i < len(s); {
406			c := s[i]
407			if c == '\\' {
408				if i+1 >= len(s) {
409					return fmt.Errorf("node contains a truncated escape")
410				}
411				if s[i+1] != 'u' {
412					i += 2
413					continue
414				}
415				if i+6 > len(s) {
416					return fmt.Errorf("node contains a truncated \\u escape")
417				}
418				r, err := parseHex4(s[i+2 : i+6])
419				if err != nil {
420					return fmt.Errorf("node contains an invalid \\u escape: %w", err)
421				}
422				switch {
423				case r >= 0xD800 && r <= 0xDBFF:
424					// A high surrogate is only valid when immediately followed
425					// by a low-surrogate \u escape.
426					if i+12 > len(s) || s[i+6] != '\\' || s[i+7] != 'u' {
427						return fmt.Errorf("node contains an unpaired high surrogate \\u%04X", r)
428					}
429					lo, err := parseHex4(s[i+8 : i+12])
430					if err != nil {
431						return fmt.Errorf("node contains an invalid \\u escape: %w", err)
432					}
433					if lo < 0xDC00 || lo > 0xDFFF {
434						return fmt.Errorf("node contains an unpaired high surrogate \\u%04X", r)
435					}
436					i += 12
437				case r >= 0xDC00 && r <= 0xDFFF:
438					return fmt.Errorf("node contains an unpaired low surrogate \\u%04X", r)
439				default:
440					i += 6
441				}
442				continue
443			}
444			if c < utf8.RuneSelf {
445				i++
446				continue
447			}
448			// A valid multi-byte rune decodes with size >= 2; size 1 means the
449			// bytes are not valid UTF-8 (including surrogate encodings).
450			_, size := utf8.DecodeRune(s[i:])
451			if size == 1 {
452				return fmt.Errorf("node contains invalid UTF-8 at byte offset %d", i)
453			}
454			i += size
455		}
456		return nil
457	}
458	
459	// parseHex4 parses exactly four hexadecimal digits as a 16-bit value.
460	func parseHex4(b []byte) (rune, error) {
461		v := 0
462		for _, c := range b {
463			var d int
464			switch {
465			case '0' <= c && c <= '9':
466				d = int(c - '0')
467			case 'a' <= c && c <= 'f':
468				d = int(c-'a') + 10
469			case 'A' <= c && c <= 'F':
470				d = int(c-'A') + 10
471			default:
472				return 0, fmt.Errorf("invalid hex digit %q", c)
473			}
474			v = v*16 + d
475		}
476		return rune(v), nil
477	}
478	
479	// parseOneHeartbeat decodes one submit-input record and applies the
480	// submit-only rule that collection time cannot be later than receive time.
481	func parseOneHeartbeat(raw json.RawMessage, receiveTime time.Time) (Heartbeat, error) {
482		h, err := decodeStrictHeartbeatObject(raw)
483		if err != nil {
484			return Heartbeat{}, err
485		}
486		if err := checkCollectedAtTiming(h.CollectedAt, receiveTime); err != nil {
487			return Heartbeat{}, err
488		}
489		return h, nil
490	}
491	
492	func containsString(list []string, s string) bool {
493		for _, v := range list {
494			if v == s {
495				return true
496			}
497		}
498		return false
499	}
