195	func cmdHealth(args []string) {
196		fs := newFlagSet("heartbeat health")
197		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
198		node := fs.String("node", "", "node id (required)")
199		atStr := fs.String("at", "", "query time (RFC3339); default: now")
200		expectedVersion := fs.String("expected-version", "", "expected version (required)")
201		toleratedMisses := fs.Int("tolerated-misses", -1, "tolerated missed duties, >= 0 (required)")
202		missedSinceSeq := fs.Int64("missed-since-seq", 0, "seq of a saved heartbeat to use as the missed-duty baseline; must be > 0 and exist for the node")
203		if err := fs.Parse(args); err != nil {
204			if err == flag.ErrHelp {
205				os.Exit(0)
206			}
207			os.Exit(2)
208		}
209		if *node == "" {
