502	// TestCLISubmitRejectsBatchTouchingCorruptNode ensures a batch is refused
503	// before any new record is saved: the corrupt file stays byte-for-byte
504	// intact, other files in the batch are not written, and no new node file is
505	// created. Submitting only to healthy nodes continues to work.
506	func TestCLISubmitRejectsBatchTouchingCorruptNode(t *testing.T) {
