	r, err := store.Health("n1", receive, "1.0", 0)
	if err != nil {
		t.Fatalf("previous data not queryable after failure: %v", err)
	}
	if r.Seq != 1 {
		t.Errorf("after failure seq=%d, want 1 (previous data intact)", r.Seq)
	}
}

